INSERT INTO `_koKR_stage_achievement_reward_locale` (`ID`, `Subject`, `Body`) VALUES
(13, '80레벨', '모험의 80번째 계절에 이르기까지 뜻을 굽히지 않은 것을 축하합니다. 아제로스를 괴롭혀 온 악을 몰아내는 일에 그대가 얼마나 헌신했는지 의심할 여지가 없습니다.$b$b여기까지 온 길도 결코 작은 일이 아니었지만, 진짜 싸움은 이제부터입니다.$b$b계속 싸워 나가십시오!$b$b로닌'),
(45, '두루 다녀 보셨군요!', '이야, 이것 좀 보게!$b$b이 얼음투성이 땅에서 볼 건 다 봤다고 생각했는데 말이지! 자네 눈에는 탐험가의 불길이 타오르고 있구먼.$b$b이 휘장을 자랑스럽게 걸치게. 그러면 길을 물어야 할 때 친구들이 누구를 찾아가야 할지 알 테니!$b$b계속 움직이게나!$b$b-브란 브론즈비어드'),
(614, '얼라이언스를 위하여!', '우리 땅 곳곳에서 전쟁이 벌어지고 있습니다. 오직 가장 용감한 영웅만이 호드의 가장 아픈 곳을 칠 수 있으며, 그대가 바로 그런 영웅입니다.$b$b그대가 호드 수뇌부에 가한 타격이 우리의 마지막 공세를 여는 문이 될 것입니다. 호드는 얼라이언스의 힘 앞에 무릎 꿇을 것입니다.$b$b그대의 공적에는 반드시 보상이 따를 것입니다. 자랑스럽게 달리십시오!$b$b--그대의 왕'),
(619, '호드를 위하여!', '이 큰 혼란의 시대에 비참함 속에서 진정한 영웅이 나타난다. 그대가 바로 그런 위대한 영웅이다.$b$b전쟁이 코앞에 닥쳤다. 그대의 노력은 아제로스에서 우리의 대의를 한층 앞당길 것이다. 그 위대한 공적에는 반드시 보상이 따르리라. 오그리마의 이 상을 받고 영광을 향해 달려라.$b$b호드를 위하여!$b$b대족장 스랄'),
(876, '잔혹하리만치 헌신적인', '꼬맹이, 내가 널 지켜봐 왔다.$b$b투기장에서 한판 붙는 데는 제법 재능이 있더군. 이걸 받아 두게. 자랑스럽게 걸치게나. 자, 이제 다시 들어가서 어떻게 하는 건지 보여 주라고!$b$b살 아저씨'),
(1021, '대단한 업적 수집가', '계절이 흐르는 동안 그대가 모아 온 훌륭한 휘장 수집품을 보지 않을 수 없었습니다. 이것도 수집품에 더하시지요. 제 옷장에서 그저 먼지만 뒤집어쓰고 있었으니까요.'),
(1250, '구린내의 새 보금자리', '털복숭이 친구들을 얼마나 잘 돌보시는지 소문 들었어요. 실례가 안 된다면, 구린내에게 새 보금자리를 찾아 주어야겠어요. 도무지 다른 아이들과 잘 어울리질 않거든요.$b$b하루에 두 번 꼭 먹이를 주세요. 그리고 음... 이 아이는 검은 고양이를 무척 좋아한답니다.$b$b--브레아니'),
(1793, '고마워요!', '$N 님께.$b$b어린이 주간에 저를 데리고 다녀 주셔서 고마워요. 혈기사단의 수장이신 리아드린 여사께서 저를 실버문으로 데려가 수련시키겠다고 하셨어요!$b$b제 친구 흐추를 만나게 해 주시고 어둠의 문, 정령의 왕좌, 시간의 동굴까지 보여 주셔서 정말 고마웠어요. 장난감 용도 정말 마음에 들어요!$b$b제 애완동물도 잘 돌봐 주고 계시겠죠. 제가 보고 싶어 한다고 전해 주세요!$b$b진심을 담아,$b살란드리아.'),
(1956, '더 높은 배움', '비전 마법 학파에 대한 연구를 마친 것을 축하합니다. 그 헌신을 기려 이 시리즈를 완성하는 특별한 책을 동봉합니다.$b$b이 책이 특히 재미있으리라 생각합니다. 다만 그건 직접 확인해 보시지요.$b$b진심을 담아,$b$b로닌'),
(2096, '동전의 달인', '인사드리며, 달라란 주화 전질을 모으신 것을 축하합니다! 그 노고에 대한 보상으로 갓 주조한 달라란의 티타늄 인장을 동봉합니다. 가장 열성적인 수집가에게만 드리는 특별한 주화지요.$b$b이 특별한 보상을 즐기시기 바랍니다. 그럴 자격이 충분하니까요!$b$b진심을 담아,$b$b제페토 조이버즈'),
(2136, '영웅의 영광', '용사여,$b$b그대가 노스렌드에 온 이래 이룬 위대한 영웅적 행적이 용의 안식처 사원에까지 전해졌습니다.$b$b그 용기가 인정받지 못한 채 묻혀서는 안 되겠지요. 위상들을 대신해 이 선물을 받아 주십시오. 우리는 함께 아제로스에서 악을 영원히 몰아낼 것입니다.$b$b생명의 인도자 알렉스트라자'),
(2143, '기병대를 이끌고', '가축을 다루는 솜씨가 얼마나 좋은지 눈에 띄더군요. 요즘 이곳이 북적거려 제 장사는 어느 때보다 잘되고 있습니다. 이 백색 비룡을 대신 돌봐 주실 수 있을까요? 이 많은 동물을 다 보살피기에는 하루가 너무 짧군요.$b$b메이 드림'),
(2144, '참으로 길고도 기이한 여정', '멀리서 전쟁의 북소리가 울리면 아제로스의 주민들은 삶이 주는 것들을 쉽게 잊곤 합니다. 하지만 그대는 우리가 무엇을 위해 싸우는지 기억하는 힘으로 아제로스 선한 종족들의 품격을 지켜 냈습니다. 승리를 기리지 않는 것 또한 또 다른 패배입니다. 축제의 주인공이여, 그것을 잘 기억하십시오. 그대의 흥겨움이 다른 이들에게도 힘이 되기를. 생명의 인도자 알렉스트라자'),
(2516, '꼬마 사냥꾼', '안녕하세요!$b$b그 말썽꾸러기 구린내에게까지 따뜻한 보금자리를 마련해 주셨다고 들었어요... 혹시 또 다른 떠돌이 아이를 맡아 주실 수 있을까요?$b$b이 작은 새끼 사슴은 수줍음이 많지만, 동봉한 가장 좋아하는 소금덩이만 있으면 금방 친해질 거예요!$b$b--브레아니'),
(2536, '탈것 산더미', '이제 그대의 마구간이 제 것 못지않게 크다고 들었습니다. 대단하군요! 서로 도움이 될 수 있을 것 같습니다...$b$b용매가 한 마리 남아서, 이 아이에게 보금자리를 마련해 주실 수 있을까 합니다. 물론 사냥용이 아니라 탈것으로 길들였고, 제가 기른 어떤 탈것 못지않게 충직하고 지치지 않을 겁니다.$b$b다시 한번, 메이 드림'),
(2537, '탈것 산더미', '이제 그대의 마구간이 제 것 못지않게 크다고 들었습니다. 대단하군요! 서로 도움이 될 수 있을 것 같습니다...$b$b용매가 한 마리 남아서, 이 아이에게 보금자리를 마련해 주실 수 있을까 합니다. 물론 사냥용이 아니라 탈것으로 길들였고, 제가 기른 어떤 탈것 못지않게 충직하고 지치지 않을 겁니다.$b$b다시 한번, 메이 드림'),
(2957, '울두아르 공격대의 영광', '$N 님께,$b$b잘 지내고 계시길 바라며, 울두아르에서 함께 벌인 소동에서 몸은 좀 추스르셨는지요.$b$b탐광대 친구들이 반쯤 죽어 가던 이 가여운 비룡 새끼를 발견했습니다. 무쇠 드워프들이 뭔가 실험을 한 모양이더군요.$b$b건강을 되찾아 주었더니 이제는 제법 커졌습니다! 우리야 숫양이랑 짐노새밖에 탈 줄 모르는 데다, 그때 그대에게 신세를 졌으니... 이 녀석을 선물로 받아 주셨으면 합니다.$b$b브란 브론즈비어드 드림'),
(2958, '영웅: 울두아르 공격대의 영광', '$N 님께,$b$b잘 지내고 계시길 바라며, 울두아르에서 함께 벌인 소동에서 몸은 좀 추스르셨는지요.$b$b탐광대 친구들이 반쯤 죽어 가던 이 가여운 비룡 새끼를 발견했습니다. 무쇠 드워프들이 뭔가 실험을 한 모양이더군요.$b$b건강을 되찾아 주었더니 이제는 제법 커졌습니다! 우리야 숫양이랑 짐노새밖에 탈 줄 모르는 데다, 그때 그대에게 신세를 졌으니... 이 녀석을 선물로 받아 주셨으면 합니다.$b$b브란 브론즈비어드 드림'),
(3478, '아직 먹히지 않은 칠면조', '이 통통한 칠면조가 11월을 살아서 넘겼다는 게 믿어지시나요?$b$b친구들은 죄다 풍성한 식탁에 크랜베리 처트니와 향신료 빵 속을 곁들여 올라갔는데... 어우... 배가 고파지네요. 아무튼! 이제 혼자 남았으니 그대가 돌봐 주셨으면 합니다. 제 가게에는 더 이상 자리가 없거든요!$b$b다만 요리용 불 근처에는 가까이 가지 못하게 해 주세요. 불만 보면 눈빛이 이상해지거든요...'),
(3857, '정복의 섬 지배자', '명예로운 $N 님께,$b$b정복의 섬에서 이룬 공적에 대해 이 휘장을 드리게 되어 영광입니다. 자랑스럽게 걸치십시오.$b$b최고사령관 핼포드 웜베인'),
(3957, '정복의 섬 지배자', '명예로운 $N 님께,$b$b정복의 섬에서 이룬 공적에 대해 이 휘장을 드리게 되어 영광입니다. 자랑스럽게 걸치십시오.$b$b대장군 아그마르'),
(4079, '불멸에 바치는 헌사', '$N 님께.$b$b대십자군의 시험에서 보여 준 그대의 활약은 앞으로 오랜 세월 동안 전해지고 또 전해질 것입니다. 은빛십자군이 아제로스 최고의 용사들에게 원형 경기장의 도가니에서 담력을 시험해 보라 외쳤을 때, 그대와 동료들 같은 빛의 등불이 그 난전에서 떠오르기를 간절히 바랐습니다.$b$b리치 왕과의 싸움이 다가오는 지금 그대의 힘이 절실합니다. 그러나 오늘만큼은 그 영광스러운 성취를 마음껏 기뻐하며, 우리의 가장 뛰어난 군마 한 마리를 선물로 받아 주십시오. 스컬지가 지평선 너머로 다가오는 그 깃발을 본다면, 영웅이여, 그들의 종말이 가까워진 것입니다!$b$b영광과 함께,$b티리온 폴드링'),
(4156, '불멸에 바치는 헌사', '$N 님께.$b$b대십자군의 시험에서 보여 준 그대의 활약은 앞으로 오랜 세월 동안 전해지고 또 전해질 것입니다. 은빛십자군이 아제로스 최고의 용사들에게 원형 경기장의 도가니에서 담력을 시험해 보라 외쳤을 때, 그대와 동료들 같은 빛의 등불이 그 난전에서 떠오르기를 간절히 바랐습니다.$b$b리치 왕과의 싸움이 다가오는 지금 그대의 힘이 절실합니다. 그러나 오늘만큼은 그 영광스러운 성취를 마음껏 기뻐하며, 우리의 가장 뛰어난 군마 한 마리를 선물로 받아 주십시오. 스컬지가 지평선 너머로 다가오는 그 깃발을 본다면, 영웅이여, 그들의 종말이 가까워진 것입니다!$b$b영광과 함께,$b티리온 폴드링'),
(4478, '무작위 파티', '참을성 많은 분께,$b$b처음 보는 사람들과 던전을 돌며 보여 준 끈기를 기리고 싶습니다. 무작위 파티에서 초보자들에게 요령도 알려 주셨겠지요.$b$b요컨대, 퍼그를 좋아하신다고 들었습니다. 그래서 퍼그를 위한 퍼그를 드립니다. 퍼그를 하면서 퍼그를 즐기시라고요. 뭐 그런 얘깁니다.$b$b포옹을 담아,$b$bWoW 개발팀 일동'),
(4602, '얼음왕관 공격대의 영광', '$N,$b$b리치 왕의 영향력이 약해지면서 그의 강력한 하수인 몇몇이 속박에서 풀려났다.$b$b부하들이 사로잡은 이 서리고룡이 바로 그런 예다. 제 뜻이 아주 강한 녀석이지.$b$b길들이다 부하 하나가 팔을 잃었지만, 지금은 기수를 꽤 잘 받아들인다. 물론 기수 자신도 솜씨와 의지가 강해야 하지만.$b$b검은 칼날 기사단이 보내는 선물로 이 훌륭한 짐승을 받아 주기 바란다. 이 위대한 전투에서 그대와 어깨를 나란히 하고 싸운 것은 영광이었다.$b$b명예를 담아,$b다리온 모그레인'),
(4603, '영웅: 얼음왕관 공격대의 영광', '$N,$b$b리치 왕의 영향력이 약해지면서 그의 강력한 하수인 몇몇이 속박에서 풀려났다.$b$b부하들이 사로잡은 이 서리고룡이 바로 그런 예다. 제 뜻이 아주 강한 녀석이지.$b$b길들이다 부하 하나가 팔을 잃었지만, 지금은 기수를 꽤 잘 받아들인다. 물론 기수 자신도 솜씨와 의지가 강해야 하지만.$b$b검은 칼날 기사단이 보내는 선물로 이 훌륭한 짐승을 받아 주기 바란다. 이 위대한 전투에서 그대와 어깨를 나란히 하고 싸운 것은 영광이었다.$b$b명예를 담아,$b다리온 모그레인'),
(4845, '되찾은 물건', '뒤틀린 황천에서 잃어버린 물건을 찾았는데 확인해 보니 귀하의 것이었습니다. 해당 물건을 동봉합니다.'),
(4853, '되찾은 물건', '뒤틀린 황천에서 잃어버린 물건을 찾았는데 확인해 보니 귀하의 것이었습니다. 해당 물건을 동봉합니다.'),
(5325, '호드의 전쟁늑대', '네 손에 얼마나 많은 얼라이언스의 머리가 흙먼지 속으로 떨어졌는가? 얼마나 많은 승리를 거두고, 적을 짓밟고, 전장을 빼앗았는가?$b$b헬스크림의 눈이 너를 지켜보았고, 그 눈은 흡족해하고 있다. 자랑스럽게 달려라, 호드를 위하여!$b$b--대족장 가로쉬 헬스크림'),
(5326, '호드의 전쟁늑대', '네 손에 얼마나 많은 얼라이언스의 머리가 흙먼지 속으로 떨어졌는가? 얼마나 많은 승리를 거두고, 적을 짓밟고, 전장을 빼앗았는가?$b$b헬스크림의 눈이 너를 지켜보았고, 그 눈은 흡족해하고 있다. 자랑스럽게 달려라, 호드를 위하여!$b$b--대족장 가로쉬 헬스크림'),
(5328, '얼라이언스의 군마', '그대의 솜씨와 용기는 전장에서 몇 번이고 증명되었습니다.$b$b그 공적에는 반드시 보상이 따를 것입니다. 자랑스럽게 달리십시오, 얼라이언스를 위하여!$b$b--그대의 왕'),
(5329, '얼라이언스의 군마', '그대의 솜씨와 용기는 전장에서 몇 번이고 증명되었습니다.$b$b그 공적에는 반드시 보상이 따를 것입니다. 자랑스럽게 달리십시오, 얼라이언스를 위하여!$b$b--그대의 왕'),
(5449, '되찾은 물건', '뒤틀린 황천에서 잃어버린 물건을 찾았는데 확인해 보니 귀하의 것이었습니다.$b$b해당 물건을 동봉합니다.'),
(5823, '얼라이언스의 군마', '그대의 솜씨와 용기는 전장에서 몇 번이고 증명되었습니다.$b$b그 공적에는 반드시 보상이 따를 것입니다. 자랑스럽게 달리십시오, 얼라이언스를 위하여!$b$b--그대의 왕'),
(5824, '호드의 전쟁늑대', '네 손에 얼마나 많은 얼라이언스의 머리가 흙먼지 속으로 떨어졌는가? 얼마나 많은 승리를 거두고, 적을 짓밟고, 전장을 빼앗았는가?$b$b헬스크림의 눈이 너를 지켜보았고, 그 눈은 흡족해하고 있다. 자랑스럽게 달려라, 호드를 위하여!$b$b--대족장 가로쉬 헬스크림'),
(5828, '되찾은 물건', '뒤틀린 황천에서 잃어버린 물건을 찾았는데 확인해 보니 귀하의 것이었습니다. 해당 물건을 동봉합니다.'),
(5859, '남겨진 것', '이 목걸이를 용암 가장자리 근처, 화염 심연에서 주웠습니다. 제 것도 아니고, 두 대드루이드의 것도 아니라는 걸 압니다. 어쩌면 불의 드루이드 중 누군가의 것이었겠지요.$b$b누구의 것이었든 제게는 쓸모가 없습니다. 우리를 위해 해 주신 모든 일에 대한 작은 감사의 표시로 받아 주십시오.'),
(5860, '제발... 그냥 데려가 주십시오', '형제가 끌려간 뒤로 이 작은 녀석은 손을 댈 수 없을 만큼 말썽입니다. 수호자들과 제가 할 수 있는 건 다 해 봤지만 그 기운을 감당하기에는 턱없이 부족했습니다. 이제 분명해졌습니다.$b$b이 아이는 형제 곁에 있고 싶어 합니다.$b$b가두는 데만 꼬박 한 시간이 걸렸습니다. 부디 데려가 주십시오. 이 동굴 밖에서 얼마간 지내면 좀 나아질지도 모르겠습니다.$b$b-파르덴 발톱매'),
(5866, '대드루이드가 보내는 선물', '다시는 하이잘이 끝없는 화염의 군세 아래 떨지 않을 것입니다. 다시는 이 세상의 필멸자들이 라그나로스의 하수인 앞에서 떨지 않을 것입니다.$b$b이제 그대의 노력 덕분에, 떨게 될 쪽은 그들입니다.$b$b용암 전선에서 보여 준 그대의 영웅적인 활약은 화염 군주와의 싸움에서 결정적이었습니다. 칼림도어 곳곳에서 동맹을 모아 하나의 군대로 만들었고, 라그나로스의 하수인들과 싸워... 이겨 냈습니다. 그 일에 깊이 감사드립니다.'),
(5875, '계속 모으세요!', '안녕하세요!$b$b와, 귀여운 동물 수집가가 다 되셨네요?$b$b응원하는 마음으로 짧은 편지와 작은 선물을 보냅니다. 계속 힘내세요!$b$b--브레아니'),
(5876, '미쳐 버리겠어요!', '또 만나네요, 친구!$b$b이 장난꾸러기 녀석 때문에 애완동물 가게 사람들이 모두 미쳐 가고 있어요!$b$b모험길에 데리고 다니시면 어떨까 해요... 세상 구경을 좀 하고 나면 진정될지도 모르니까요.$b$b투구는 꼭 쓰고 계시죠...?$b$b--브레아니'),
(5877, '계속 모으세요!', '안녕하세요!$b$b와, 귀여운 동물 수집가가 다 되셨네요?$b$b응원하는 마음으로 짧은 편지와 작은 선물을 보냅니다. 계속 힘내세요!$b$b--브레아니'),
(6169, '되찾은 물건', '뒤틀린 황천에서 잃어버린 물건을 찾았는데 확인해 보니 귀하의 것이었습니다. 해당 물건을 동봉합니다.'),
(6375, '용맹한 업적을 기리며', '축하합니다.$B$B눈앞의 막강한 도전을 정복한 것은 칭송받아 마땅한 업적입니다. 이 위대한 공적을 기리며 선조의 불사조 알을 맡깁니다. 영원꽃 골짜기에 있는 저를 찾아와 함께할 불사조를 선택하십시오.'),
(6716, '사우록의 비밀', '안녕하시오, $n.$b$b두려운 사우록에 관해 많은 것을 배웠다고 들었소. 이 고대의 적은 겉으로 보이는 것보다 훨씬 많은 비밀을 품고 있소. 지식의 연단으로 와서 서로의 기록을 비교해 봅시다!$b$b우리 위치가 표시된 지도를 함께 보냈소. 다음 만남을 기대하겠소.$b$b진심을 담아,$b전승지기 초'),
(6754, '모구의 역사', '안녕하시오, $n.$b$b고대 모구에 관한 연구가 잘 진행되고 있다고 들었소. 그들의 위대한 고대 제국과 순식간에 찾아온 몰락에서 많은 것을 배울 수 있소. 지식의 연단으로 오면 오랜 적에 관한 새로운 관점을 나누겠소.$b$b우리 위치가 표시된 지도를 함께 보냈소. 다음 만남을 기대하겠소.$b$b진심을 담아,$b전승지기 초'),
(6827, '판다렌 대사', '안녕하시오, 여행자여!$b$b이 지역의 판다렌 세력에 그토록 헌신한 이는 오랜만이오. 높은 경지에 이르기까지 수많은 날 동안 힘써 주었소.$b$b감사의 표시를 받아 주시오. 판다리아는 언제나 당신을 환영할 것이오.$b$b- 전승지기 초'),
(6828, '판다렌 대사', '안녕하시오, 여행자여!$b$b이 지역의 판다렌 세력에 그토록 헌신한 이는 오랜만이오. 높은 경지에 이르기까지 수많은 날 동안 힘써 주었소.$b$b감사의 표시를 받아 주시오. 판다리아는 언제나 당신을 환영할 것이오.$b$b- 전승지기 초'),
(6846, '진위 연구', '안녕하시오, $n.$b$b영리한 진위에 관해 많은 것을 배웠다고 들었소. 지식의 연단으로 와서 그 지혜를 우리와 나누는 것이 어떻겠소?$b$b우리 위치가 표시된 지도를 함께 보냈소. 다음 만남을 기대하겠소.$b$b진심을 담아,$b전승지기 초'),
(6847, '야운골 이해하기', '안녕하시오, $n.$b$b약탈을 일삼는 야운골을 연구해 왔다고 들었소. 이 강인한 종족은 겉으로 보이는 것보다 훨씬 복잡하오. 지식의 연단으로 오면 내 관점을 나누며 이야기해 봅시다.$b$b우리 위치가 표시된 지도를 함께 보냈소.$b$b진심을 담아,$b전승지기 초'),
(6850, '호젠 연구', '안녕하시오, $n.$b$b호젠의 본성에 관해 조사해 왔다고 들었소. 몹시 제멋대로인 이들을 연구하다니 용감하군! 지식의 연단으로 와서 서로 배운 것을 비교해 봅시다.$b$b우리 위치가 표시된 지도를 함께 보냈소.$b$b진심을 담아,$b전승지기 초'),
(6855, '샤오하오의 가르침', '안녕하시오, $n.$b$b우리의 마지막이자 가장 위대한 황제 샤오하오의 길을 걸었다고 들었소. 내게도 매우 소중한 주제라 오랫동안 그의 여정을 연구해 왔소. 지식의 연단으로 와서 이야기해 봅시다!$b$b우리 위치가 표시된 지도를 함께 보냈소.$b$b진심을 담아,$b전승지기 초'),
(6856, '리우 랑의 모험', '안녕하시오, $n.$b$b방랑자 리우 랑의 놀라운 이야기를 발견했다고 들었소. 지식의 연단으로 와서 그 지혜를 우리와 나누는 것이 어떻겠소?$b$b우리 위치가 표시된 지도를 함께 보냈소.$b$b진심을 담아,$b전승지기 초'),
(6857, '사마귀족의 비밀', '안녕하시오, $n.$b$b사마귀족의 어두운 비밀을 밝히기 위해 모험했다고 들었소. 지식의 연단으로 오면 이 독특한 문화에 관한 관점을 나누겠소.$b$b우리 위치가 표시된 지도를 함께 보냈소.$b$b진심을 담아,$b전승지기 초'),
(6858, '과거 영웅들의 용기', '안녕하시오, $n.$b$b판다렌의 전투 역사와 그 기술을 세운 영웅들을 연구해 왔다고 들었소. 지식의 연단으로 와서 배운 내용을 현재의 역사 기록과 비교해 봅시다.$b$b우리 위치가 표시된 지도를 함께 보냈소.$b$b진심을 담아,$b전승지기 초'),
(7934, '미스터 비글스워스', '[임시 문구]'),
(7939, '싸움꾼 조합 초대장', '싸울가르 투기장에서 꽤 많은 추종자를 모았더군! 자네 친구들의 실력도 궁금해졌네.$b$b나눠 줄 초대장을 보냈으니 새로운 피를 수혈해 보게!$b$b- 감독관 바젤플랜지'),
(7940, '싸움꾼 조합 초대장', '비즈모의 싸움굴에서 꽤 많은 추종자를 모았군요! 당신 친구들의 실력도 궁금해졌습니다.$b$b나눠 줄 초대장을 보냈으니 새로운 싸움꾼을 데려오세요!$b$b- 비즈모'),
(8302, '무장한 붉은 용매', '업적 보상으로 무장한 붉은 용매를 보내드립니다. 자랑스럽게 타십시오!'),
(8304, '무장한 푸른 용매', '업적 보상으로 무장한 푸른 용매를 보내드립니다. 자랑스럽게 타십시오!'),
(8484, '흉포한 안장', '전장에서 거둔 승리를 기리며 흉포한 안장을 보내드립니다.'),
(8485, '흉포한 안장', '전장에서 거둔 승리를 기리며 흉포한 안장을 보내드립니다.');
INSERT INTO `achievement_reward_locale` (`ID`, `Locale`, `Subject`, `Body`)
