-- Korean locale additions for `achievement_reward_locale`.
-- Update existing rows and insert missing rows only when the parent exists.
-- Preserve existing Korean text and other locales.
DROP TEMPORARY TABLE IF EXISTS `_koKR_stage_achievement_reward_locale`;
CREATE TEMPORARY TABLE `_koKR_stage_achievement_reward_locale` (
    `ID` INT UNSIGNED NOT NULL,
    `Subject` LONGTEXT NULL,
    `Body` LONGTEXT NULL,
    PRIMARY KEY (`ID`)
) ENGINE=InnoDB;


UPDATE `achievement_reward_locale` AS `l`
INNER JOIN `_koKR_stage_achievement_reward_locale` AS `s` ON `l`.`ID` = `s`.`ID` AND `l`.`Locale` = 'koKR'
INNER JOIN `achievement_reward` AS `p` ON `p`.`entry` = `s`.`ID`
SET `l`.`Subject` = IF(`s`.`Subject` IS NOT NULL AND (`l`.`Subject` IS NULL OR `l`.`Subject` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Subject`, `l`.`Subject`),
    `l`.`Body` = IF(`s`.`Body` IS NOT NULL AND (`l`.`Body` IS NULL OR `l`.`Body` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Body`, `l`.`Body`);

SELECT `s`.`ID`, 'koKR', `s`.`Subject`, `s`.`Body`
FROM `_koKR_stage_achievement_reward_locale` AS `s`
INNER JOIN `achievement_reward` AS `p` ON `p`.`entry` = `s`.`ID`
LEFT JOIN `achievement_reward_locale` AS `l` ON `l`.`ID` = `s`.`ID` AND `l`.`Locale` = 'koKR'
WHERE `l`.`ID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_achievement_reward_locale`;
